/**
 * Localized emoji search terms from CLDR — the same annotation data that gives
 * the English catalog its keywords, which CLDR also publishes per locale. A
 * student whose browser is in Spanish can then find ❤️ by typing "corazón",
 * and 🪰 by "mosca", without the picker switching languages on them.
 *
 * The files are generated by scripts/build-emoji-locale-kw.mjs into
 * static/emoji-kw/<locale>.json: { "<glyph>": "name|keyword|keyword…" }.
 * Only the visitor's own language is fetched, once, and English visitors fetch
 * nothing at all (their keywords are already in emoji-data.json).
 */
const LOCALE_FILES_URL = '/emoji-kw';

let loaded = null;   // { tag, terms: Map<glyphKey, string[]> }
let loading = null;
let available = null;

const glyphKey = (text) => text.replaceAll('️', '');

/** en, en-US, and no locale at all are already covered by the bundled catalog. */
export function localeTagFor(languages = navigator?.languages ?? []) {
	const tags = (Array.isArray(languages) ? languages : [languages]).filter(Boolean);
	for (const tag of tags) {
		const lower = String(tag).toLowerCase();
		if (lower === 'en' || lower.startsWith('en-')) return null; // English already bundled
		const [lang, ...rest] = String(tag).split('-');
		// zh-Hant-TW → zh-Hant (CLDR's zh_Hant), zh-TW → zh-Hant, pt-BR → pt.
		const script = rest.find((part) => part.length === 4);
		if (lang === 'zh') {
			const region = rest.find((part) => part.length === 2)?.toUpperCase();
			if (script === 'Hant' || region === 'TW' || region === 'HK' || region === 'MO') return 'zh-Hant';
			return 'zh';
		}
		return script ? `${lang}-${script}` : lang;
	}
	return null;
}

async function listAvailable() {
	available ??= fetch(`${LOCALE_FILES_URL}/index.json`)
		.then((r) => (r.ok ? r.json() : []))
		.catch(() => []);
	return available;
}

/**
 * Load the visitor's locale keywords, or null when there's nothing to add.
 * Safe to call repeatedly — one fetch per page, cached after that.
 */
export async function loadLocaleKeywords(tag = localeTagFor()) {
	if (typeof window === 'undefined' || !tag) return null;
	if (loaded?.tag === tag) return loaded;
	if (loading?.tag === tag) return loading.promise;

	const promise = (async () => {
		const locales = await listAvailable();
		// Fall back to the bare language when the exact tag isn't shipped.
		const pick = locales.includes(tag) ? tag : locales.includes(tag.split('-')[0]) ? tag.split('-')[0] : null;
		if (!pick) return null;
		try {
			const raw = await fetch(`${LOCALE_FILES_URL}/${pick}.json`).then((r) => (r.ok ? r.json() : null));
			if (!raw) return null;
			const terms = new Map();
			for (const [glyph, joined] of Object.entries(raw)) terms.set(glyphKey(glyph), joined.split('|'));
			loaded = { tag, locale: pick, terms };
			return loaded;
		} catch {
			return null; // keyword search in English still works
		}
	})();

	loading = { tag, promise };
	return promise;
}

/** What's already loaded, for synchronous consumers (the search index). */
export function localeKeywords() {
	return loaded;
}
